function isPlainObject(v) {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

export function merge(base, patch) {
  const out = {};
  for (const [key, value] of Object.entries(base)) {
    out[key] = isPlainObject(value) ? merge(value, {}) : Array.isArray(value) ? [...value] : value;
  }
  for (const [key, value] of Object.entries(patch)) {
    if (value === null) { delete out[key]; continue; }
    if (Array.isArray(value)) { out[key] = [...value]; continue; }
    if (isPlainObject(value) && isPlainObject(out[key])) { out[key] = merge(out[key], value); continue; }
    out[key] = isPlainObject(value) ? merge(value, {}) : value;
  }
  return out;
}

